/**
 * Expo config plugin — keep the Android release build uploadable to Play.
 *
 * Two things break silently when `android/` is regenerated by `expo prebuild`
 * (the `android/` folder is git-ignored in this project, so hand edits to it
 * are lost):
 *
 * 1. 16 KB page-size alignment.
 *    Google Play rejects any release whose 64-bit native libraries are only
 *    4 KB aligned ("Your app does not support 16 KB memory page sizes").
 *    Older Expo templates hardcoded `com.facebook.fresco:animated-gif:2.5.0`
 *    and `:webpsupport:2.5.0`; those AARs ship `libgifimage.so` /
 *    `libstatic-webp.so` with ELF `PT_LOAD p_align = 0x1000` (4 KB).
 *    React Native ships Fresco 3.6.0, which is 16 KB aligned, so this plugin
 *    forces every `com.facebook.fresco` dependency onto that version.
 *
 * 2. Release signing.
 *    The generated template signs the release build with the DEBUG key. An
 *    upload signed with the wrong key is rejected by Play ("upload key not
 *    recognised") and users cannot upgrade over the installed app. The
 *    credentials are read from environment variables so no secret ever lands
 *    in git:
 *
 *      HYMNBOOK_KEYSTORE_PATH       absolute path to the release keystore
 *      HYMNBOOK_KEYSTORE_PASSWORD   keystore password
 *      HYMNBOOK_KEY_ALIAS           key alias
 *      HYMNBOOK_KEY_PASSWORD        key password
 *
 *    When they are not set the plugin leaves the template untouched (debug
 *    signing) and prints a warning, so a developer build still works.
 */
const { withAppBuildGradle } = require("@expo/config-plugins");

const FRESCO_VERSION = "3.6.0";

const PIN_BLOCK = `
// Force a single, 16 KB page-size aligned Fresco version across the app.
// The Expo template can hardcode fresco 2.5.0 for GIF/WebP, whose .so
// libraries are only 4 KB aligned and make Google Play reject the release
// ("Your app does not support 16 KB memory page sizes").
// Match React Native's own Fresco version (aligned in the bundled artifacts).
configurations.all {
    resolutionStrategy.eachDependency { details ->
        if (details.requested.group == "com.facebook.fresco") {
            details.useVersion("${FRESCO_VERSION}")
        }
    }
}
`;

const MANIFEST_PLACEHOLDER_BLOCK = `
        // 16KB page size support
        manifestPlaceholders = [
            enable16KBPages: "true"
        ]
`;

/**
 * Find the block that starts with `header` (e.g. "signingConfigs {") and
 * return the index of its matching closing brace.
 */
function findBlockEnd(text, header) {
  const start = text.indexOf(header);
  if (start === -1) return -1;
  let depth = 0;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (ch === "{") depth++;
    else if (ch === "}") {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function applyFrescoPin(contents) {
  let result = contents;

  if (!result.includes("details.useVersion(")) {
    const marker = "\ndependencies {";
    const index = result.indexOf(marker);
    if (index === -1) {
      throw new Error(
        '[with-android-release-config] Could not find the "dependencies {" block in android/app/build.gradle'
      );
    }
    result = result.slice(0, index) + "\n" + PIN_BLOCK + result.slice(index);
  }

  // Replace explicit Fresco coordinates (2.5.0 or the Expo version catalog)
  // with the pinned, aligned version. The version token runs up to the
  // closing quote so expressions such as ${expoLibs.versions.fresco.get()}
  // are replaced as a whole.
  result = result.replace(
    /com\.facebook\.fresco:(animated-gif|webpsupport|animated-webp):[^"']+/g,
    `com.facebook.fresco:$1:${FRESCO_VERSION}`
  );

  if (!result.includes("enable16KBPages")) {
    const defaultConfig = /defaultConfig \{/;
    if (defaultConfig.test(result)) {
      // Use a function replacement: a string replacement would treat "$1" as a
      // backreference (and leave a literal "$1" behind, as the regex has no
      // capture group) and would break the Gradle file.
      result = result.replace(
        defaultConfig,
        (match) => `${match}${MANIFEST_PLACEHOLDER_BLOCK}`
      );
    }
  }

  return result;
}

function applyReleaseSigning(contents) {
  const keystorePath = process.env.HYMNBOOK_KEYSTORE_PATH;
  const keystorePassword = process.env.HYMNBOOK_KEYSTORE_PASSWORD;
  const keyAlias = process.env.HYMNBOOK_KEY_ALIAS;
  const keyPassword = process.env.HYMNBOOK_KEY_PASSWORD;

  if (!keystorePath || !keystorePassword || !keyAlias || !keyPassword) {
    console.warn(
      "[with-android-release-config] Release signing env vars are not set " +
        "(HYMNBOOK_KEYSTORE_PATH / HYMNBOOK_KEYSTORE_PASSWORD / HYMNBOOK_KEY_ALIAS / " +
        "HYMNBOOK_KEY_PASSWORD) — the release build will be signed with the DEBUG key. " +
        "Play will reject that upload."
    );
    return contents;
  }

  if (contents.includes("signingConfigs.release")) {
    return contents; // already applied
  }

  const signingConfigsEnd = findBlockEnd(contents, "signingConfigs {");
  if (signingConfigsEnd === -1) {
    throw new Error(
      "[with-android-release-config] Could not find the signingConfigs block in android/app/build.gradle"
    );
  }

  const releaseConfig = `
        release {
            storeFile file("${keystorePath}")
            storePassword "${keystorePassword}"
            keyAlias "${keyAlias}"
            keyPassword "${keyPassword}"
        }
`;

  // Insert on its own line, keeping the original indentation of the block.
  const signingConfigsLineStart = contents.lastIndexOf("\n", signingConfigsEnd) + 1;
  let result =
    contents.slice(0, signingConfigsLineStart) +
    releaseConfig +
    contents.slice(signingConfigsLineStart);

  // Point the release build type at the release signing config.
  const buildTypesStart = result.indexOf("buildTypes {");
  const buildTypesEnd = findBlockEnd(result, "buildTypes {");
  if (buildTypesStart === -1 || buildTypesEnd === -1) {
    throw new Error(
      "[with-android-release-config] Could not find the buildTypes block in android/app/build.gradle"
    );
  }
  const releaseTypeStart = result.indexOf("release {", buildTypesStart);
  if (releaseTypeStart === -1) {
    throw new Error(
      "[with-android-release-config] Could not find the release build type in android/app/build.gradle"
    );
  }
  const releaseTypeEnd = findBlockEnd(result.slice(releaseTypeStart), "release {");
  if (releaseTypeEnd === -1) {
    throw new Error(
      "[with-android-release-config] Could not parse the release build type in android/app/build.gradle"
    );
  }
  const absoluteReleaseEnd = releaseTypeStart + releaseTypeEnd;

  const releaseType = result.slice(releaseTypeStart, absoluteReleaseEnd);
  const patchedReleaseType = releaseType.replace(
    /signingConfig signingConfigs\.debug/,
    "signingConfig signingConfigs.release"
  );

  result =
    result.slice(0, releaseTypeStart) + patchedReleaseType + result.slice(absoluteReleaseEnd);

  return result;
}

function withAndroidReleaseConfig(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== "groovy") {
      return config;
    }

    config.modResults.contents = applyReleaseSigning(
      applyFrescoPin(config.modResults.contents)
    );

    return config;
  });
}

module.exports = withAndroidReleaseConfig;
